import math

def american_probability(value):
    if isinstance(value, bool):
        raise ValueError("Boolean values are not accepted")

    # Handle numeric strings
    if isinstance(value, str):
        stripped = value.strip()
        if not stripped:
            raise ValueError("Empty string is not a valid number")
        try:
            value = float(stripped)
        except ValueError:
            raise ValueError(f"Invalid numeric string: {value}")

    # Check for non-numeric types
    if not isinstance(value, (int, float)):
        raise ValueError(f"Unsupported type: {type(value)}")

    # Check for NaN or Infinity
    if math.isnan(value) or math.isinf(value):
        raise ValueError("Value must be finite")

    # Check absolute value constraint
    if abs(value) < 100:
        raise ValueError(f"Absolute value must be >= 100, got {abs(value)}")

    # Calculate implied probability
    if value > 0:
        return 100 / (value + 100)
    else:
        return -value / (-value + 100)

