from datetime import datetime, timezone
from odds import american_probability

def select_latest(rows, asof):
    # Validate asof
    if not isinstance(asof, datetime):
        raise ValueError("asof must be a datetime object")

    if asof.tzinfo is None:
        raise ValueError("asof must be timezone-aware")

    if not rows:
        return None

    best_row = None
    best_observed_at = None
    best_id = None

    for row in rows:
        # Check if row is a dict
        if not isinstance(row, dict):
            continue

        # Extract fields
        row_id = row.get('id')
        odds_val = row.get('odds')
        observed_at_str = row.get('observed_at')
        expires_at_str = row.get('expires_at')

        # Validate id: must be nonempty string
        if not isinstance(row_id, str) or not row_id.strip():
            continue

        # Validate odds: must be valid for american_probability
        try:
            # We need to check if odds is acceptable by american_probability
            # But we don't want to compute the probability yet, just validate
            # Let's use a helper to validate without computing
            _validate_odds(odds_val)
        except (ValueError, TypeError):
            continue

        # Validate timestamps: must be valid ISO strings that parse to aware datetimes
        try:
            observed_at = _parse_iso_timestamp(observed_at_str)
            expires_at = _parse_iso_timestamp(expires_at_str)
        except (ValueError, TypeError):
            continue

        # Check if timestamps are timezone-aware
        if observed_at.tzinfo is None or expires_at.tzinfo is None:
            continue

        # Check constraints: observed_at <= asof < expires_at and observed_at < expires_at
        if not (observed_at <= asof < expires_at):
            continue

        # This row is eligible
        # Compare with current best
        if best_row is None:
            best_row = row
            best_observed_at = observed_at
            best_id = row_id
        else:
            # Compare observed_at (latest wins)
            if observed_at > best_observed_at:
                best_row = row
                best_observed_at = observed_at
                best_id = row_id
            elif observed_at == best_observed_at:
                # Tie-break: lexicographically smallest id
                if row_id < best_id:
                    best_row = row
                    best_observed_at = observed_at
                    best_id = row_id

    return best_row

def _validate_odds(odds_val):
    """Validate odds value without computing probability."""
    if isinstance(odds_val, bool):
        raise ValueError("Boolean values are not accepted")

    # Handle numeric strings
    if isinstance(odds_val, str):
        stripped = odds_val.strip()
        if not stripped:
            raise ValueError("Empty string is not a valid number")
        try:
            val = float(stripped)
        except ValueError:
            raise ValueError(f"Invalid numeric string: {odds_val}")
        # Check finite
        import math
        if math.isnan(val) or math.isinf(val):
            raise ValueError("Value must be finite")
    elif isinstance(odds_val, (int, float)):
        import math
        if math.isnan(odds_val) or math.isinf(odds_val):
            raise ValueError("Value must be finite")
    else:
        raise ValueError(f"Unsupported type: {type(odds_val)}")

def _parse_iso_timestamp(ts_str):
    """Parse ISO timestamp string to timezone-aware datetime."""
    if not isinstance(ts_str, str):
        raise ValueError("Timestamp must be a string")

    # Handle 'Z' suffix
    ts_str = ts_str.strip()
    if ts_str.endswith('Z'):
        ts_str = ts_str[:-1] + '+00:00'

    # Try parsing with timezone info
    try:
        # Python 3.7+ supports fromisoformat with some limitations
        # We need to handle offsets like +00:00, -05:00, etc.
        dt = datetime.fromisoformat(ts_str)
    except ValueError:
        raise ValueError(f"Invalid ISO timestamp: {ts_str}")

    # Ensure timezone-aware
    if dt.tzinfo is None:
        raise ValueError("Timestamp must be timezone-aware")

    return dt
